    except (KeyboardInterrupt, EOFError):
        stopped.set()
        print()
    except OSError:
        print("Соединение с сервером потеряно")
    finally:
        stopped.set()
        try:
            connection.shutdown(socket.SHUT_RDWR)
        except OSError:
            pass
        if receiver.is_alive():
            receiver.join(JOIN_TIMEOUT)
        connection.close()
        if joined:
            print("Вы вышли из чата")


if __name__ == "__main__":
    main()
